                }

                // 2. Группируем туры по годам и сезонам
                $tours_by_years = [];

                foreach ($nearest_tours as $tour) {
                    $year = date('Y', strtotime($tour['start_date']));
                    $month = (int)date('n', strtotime($tour['start_date']));

                    // Определяем сезон
                    if ($month === 12 || $month === 1 || $month === 2) {
                        $season = 'winter';
                        $season_order = 1;
                    } elseif ($month >= 3 && $month <= 5) {
                        $season = 'spring';
                        $season_order = 2;
                    } elseif ($month >= 6 && $month <= 8) {
                        $season = 'summer';
                        $season_order = 3;
                    } else {
                        $season = 'autumn';
                        $season_order = 4;
                    }

                    $tours_by_years[$year][$season][] = $tour;
                }

                // Сортируем годы по возрастанию
                ksort($tours_by_years);
                ?>

                <!-- 3. Выводим календарь с разбивкой по годам и сезонам -->
                <div class="calendar__years">

                    <?php foreach ($tours_by_years as $year => $seasons): ?>

                        <!-- Заголовок года -->
                        <div class="calendar__year">
                            <h2 class="calendar__year-title">
                                <?php echo $year; ?>
                            </h2>

                            <div class="calendar__seasons">

                                <?php
                                // Порядок сезонов
                                $season_order = [
                                    'winter' => 1,
                                    'spring' => 2,
                                    'summer' => 3,
                                    'autumn' => 4
                                ];

                                // Сортируем сезоны
                                uksort($seasons, function($a, $b) use ($season_order) {
                                    return $season_order[$a] <=> $season_order[$b];
                                });
                                ?>

                                <?php foreach ($seasons as $season => $tours): ?>

                                    <div class="calendar__season-block">

                                        <!-- Заголовок сезона -->
                                        <h2 class="calendar__season-title">
                                            <?php echo getSeasonName($tours[0]['start_date']); ?>
                                        </h2>

                                        <div class="calendar__grid">

                                            <?php foreach ($tours as $tour): ?>

                                                <a href="trip-new.php?id=<?php echo $tour['id']; ?>"
                                                class="calendar__card <?php echo htmlspecialchars(getTripClass($tour['start_date'], $tour['end_date'])); ?>">

                                                    <p class="calendar__card-dates">
                                                        <?php 
                                                        $start_formatted = formatDate($tour['start_date']);
                                                        $end_formatted = formatDate($tour['end_date']);
                                                        
                                                        if ($start_formatted === $end_formatted) {
                                                            echo $start_formatted;
                                                        } else {
                                                            echo $start_formatted . ' - ' . $end_formatted;
                                                        }
                                                        ?>
                                                    </p>

                                                    <h3 class="calendar__card-title">
                                                        <?php echo htmlspecialchars($tour['full_title'] ?: $tour['short_title']); ?>
                                                    </h3>

                                                    <?php echo file_get_contents('sources/img/arrow.svg'); ?>
                                                </a>
                                            <?php endforeach; ?>
                                        </div>
                                    </div>
                                <?php endforeach; ?>
                            </div>
                        </div>
                    <?php endforeach; ?>
                </div>
            <?php endif; ?>
        </section>
        <hr>
        <?php include("blocks/form.php") ?>
    </main>

